solution:
function reverseString(str) {
  // accumulate characters from back to front
  let result = '';
  // start at the last index, stop when i goes below 0
  for (let i = str.length - 1; i >= 0; i--) {
    // append each character to the growing result
    result += str[i];
  }
  return result;
}

