function lastIndexOf(arr, target) {
  // scan right-to-left so the first match we find is the last in the array
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i] === target) {
      // this is the rightmost (last) occurrence
      return i;
    }
  }
  // target was never found
  return -1;
}

